CREATE TABLE IF NOT EXISTS "Guests" (
	"guest_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"guest_name" VARCHAR(255) NOT NULL,
	"g_phone" VARCHAR(15) NOT NULL CONSTRAINT chk_phone CHECK (g_phone ~ '^\+[1-9]\d{1,13}$'),
	"g_document_number" VARCHAR(50),
	"g_document_type" VARCHAR(50) CONSTRAINT chk_doc_type CHECK (g_document_type IN ('id', 'passport', 'driver license')),
	"g_email" VARCHAR(255),
	"g_created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("guest_id"),
	CONSTRAINT "Guests_unique_0" UNIQUE ("g_document_number", "g_document_type")
);

CREATE TABLE IF NOT EXISTS "Rooms" (
	"room_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"room_number" INTEGER NOT NULL,
	"hotel_id" INTEGER NOT NULL,
	"r_basic_capacity" INTEGER NOT NULL CHECK ("r_basic_capacity" >= 1),
	"r_additional_capacity" INTEGER NOT NULL DEFAULT 0,
	"r_bed_type" VARCHAR(50) NOT NULL CONSTRAINT chk_bed_type CHECK (r_bed_type IN ('single', 'double', 'both')),
	"r_view" BOOLEAN NOT NULL,
	"r_jacuzzi" BOOLEAN NOT NULL,
	PRIMARY KEY("room_id"),
	CONSTRAINT "Rooms_unique_0" UNIQUE ("hotel_id", "room_number")
);

CREATE TABLE IF NOT EXISTS "Room_pricing_changes" (
	"room_id" INTEGER NOT NULL,
	"r_price_valid_from" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	-- current price's date_till is 01/01/2099
	"r_price_valid_till" TIMESTAMPTZ NOT NULL DEFAULT '2099-01-01 00:00:00+00',
	"r_basic_price" NUMERIC(10,2) NOT NULL,
	"r_additional_guest_price" NUMERIC(10,2) NOT NULL DEFAULT 0,
	"r_high_season_rate" NUMERIC(3,2) NOT NULL DEFAULT 1,
	"r_weekend_rate" NUMERIC(3,2) NOT NULL DEFAULT 1,
	PRIMARY KEY("room_id", "r_price_valid_from"),
	CONSTRAINT chk_r_price_date CHECK (r_price_valid_till > r_price_valid_from)
);

CREATE OR REPLACE FUNCTION room_price_before_insert() RETURNS trigger AS $$
BEGIN
    -- 1) close current price
    IF NEW."r_price_valid_till" = '2099-01-01 00:00:00+00' THEN
        UPDATE "Room_pricing_changes"
        SET    "r_price_valid_till" = NEW."r_price_valid_from"
        WHERE  "room_id" = NEW."room_id"
          AND  "r_price_valid_till" = '2099-01-01 00:00:00+00'
          AND  "r_price_valid_from" < NEW."r_price_valid_from";
    END IF;

    -- 2) check dates overlapping
    IF EXISTS (
        SELECT 1 FROM "Room_pricing_changes" p
        WHERE  p."room_id" = NEW."room_id"
          AND  p."r_price_valid_from" < NEW."r_price_valid_till"
          AND  NEW."r_price_valid_from" < p."r_price_valid_till"
    ) THEN
        RAISE EXCEPTION 'Price period % - % overlaps an existing price of room %',
              NEW."r_price_valid_from", NEW."r_price_valid_till", NEW."room_id";
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_room_price_before_insert
BEFORE INSERT ON "Room_pricing_changes"
FOR EACH ROW EXECUTE FUNCTION room_price_before_insert();

