CREATE TABLE IF NOT EXISTS "Bookings" (
	"booking_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"b_created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	-- this fields has impact on view that shows rooms availability
	"b_stay_from" TIMESTAMPTZ NOT NULL,
	-- this fields has impact on view that shows rooms availability
	"b_stay_till" TIMESTAMPTZ NOT NULL,
	"guest_id" INTEGER NOT NULL,
	"is_prepaid" BOOLEAN NOT NULL,
	"b_handled_by" INTEGER NOT NULL,
	PRIMARY KEY("booking_id"),
	CONSTRAINT chk_stay_date CHECK (b_stay_till > b_stay_from)
);

COMMENT ON COLUMN "Bookings"."b_stay_from" IS 'this fields has impact on view that shows rooms availability';
COMMENT ON COLUMN "Bookings"."b_stay_till" IS 'this fields has impact on view that shows rooms availability';

CREATE TABLE IF NOT EXISTS "Booking_details" (
	"booking_id" BIGINT NOT NULL,
	-- this fields has impact on view that shows rooms availability
	"room_id" INTEGER NOT NULL,
	"guests_number" INTEGER NOT NULL,
	PRIMARY KEY("booking_id", "room_id")
);

COMMENT ON COLUMN "Booking_details"."room_id" IS 'this fields has impact on view that shows rooms availability';

CREATE TABLE IF NOT EXISTS "Booking_status" (
	"booking_status_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"booking_status_name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("booking_status_id")
);

CREATE TABLE IF NOT EXISTS "Booking_status_history" (
	"booking_id" BIGINT NOT NULL,
	"changed_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	"booking_status_id" INTEGER NOT NULL,
	PRIMARY KEY("booking_id", "changed_at")
);

CREATE TABLE IF NOT EXISTS "Booking_services" (
	"booking_id" BIGINT NOT NULL,
	"service_id" INTEGER NOT NULL,
	"s_handled_by" INTEGER,
	"quantity" INTEGER NOT NULL CHECK ("quantity" > 0),
	PRIMARY KEY("booking_id", "service_id")
);

-- availability check: rooms booked in a date range
CREATE VIEW "Room_occupied_periods" AS
SELECT bd.room_id, r.hotel_id, r.room_number,
       b.booking_id, b.b_stay_from, b.b_stay_till
FROM   "Booking_details" bd
JOIN   "Bookings" b ON b.booking_id = bd.booking_id
JOIN   "Rooms"    r ON r.room_id    = bd.room_id
WHERE  (SELECT s.booking_status_name
        FROM   "Booking_status_history" h
        JOIN   "Booking_status" s ON s.booking_status_id = h.booking_status_id
        WHERE  h.booking_id = b.booking_id
        ORDER  BY h.changed_at DESC
        LIMIT  1) IS DISTINCT FROM 'cancelled';


CREATE TABLE IF NOT EXISTS "Customer_invoices" (
	"invoice_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"inv_sum" NUMERIC(10,2) NOT NULL,
	"discount" NUMERIC(3,2) NOT NULL DEFAULT 0,
	"booking_id" BIGINT UNIQUE,
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("invoice_id")
);

CREATE TABLE IF NOT EXISTS "Customer_payments" (
	"receipt_id" BIGINT NOT NULL,
	"payment_at" TIMESTAMPTZ NOT NULL,
	"invoice_id" BIGINT NOT NULL,
	"payment_method" VARCHAR(50) NOT NULL CONSTRAINT chk_pay_method CHECK (payment_method IN ('card', 'cash', 'other')),
	"payment_sum" NUMERIC(10,2) NOT NULL,
	"payment_status" VARCHAR(20) NOT NULL CHECK (payment_status IN ('pending','completed','failed','refunded')),
	PRIMARY KEY("receipt_id"),
	CONSTRAINT "Customer_payments_unique_0" UNIQUE ("payment_at", "invoice_id")
);

CREATE TABLE IF NOT EXISTS "Services" (
	"service_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"service_name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("service_id")
);

CREATE TABLE IF NOT EXISTS "Additional_services_pricing" (
	"service_id" INTEGER NOT NULL,
	"s_price_valid_from" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	-- current price date_till is 01/01/2099
	"s_price_valid_till" TIMESTAMPTZ NOT NULL DEFAULT '2099-01-01 00:00:00+00',
	"s_price" NUMERIC(10,2) NOT NULL,
	PRIMARY KEY("service_id", "s_price_valid_from"),
	CONSTRAINT chk_s_price_date CHECK (s_price_valid_till > s_price_valid_from)
);

CREATE OR REPLACE FUNCTION service_price_before_insert() RETURNS trigger AS $$
BEGIN
    -- 1) close current price
  IF NEW."s_price_valid_till" = '2099-01-01 00:00:00+00' THEN
        UPDATE "Additional_services_pricing"
        SET    "s_price_valid_till" = NEW."s_price_valid_from"
        WHERE  "service_id" = NEW."service_id"
          AND  "s_price_valid_till" = '2099-01-01 00:00:00+00'
          AND  "s_price_valid_from" < NEW."s_price_valid_from";
    END IF;

    -- 2) check dates overlapping
    IF EXISTS (
        SELECT 1 FROM "Additional_services_pricing" p
        WHERE  p."service_id" = NEW."service_id"
          AND  p."s_price_valid_from" < NEW."s_price_valid_till"
          AND  NEW."s_price_valid_from" < p."s_price_valid_till"
    ) THEN
        RAISE EXCEPTION 'Price period % - % overlaps an existing price of service %',
              NEW."s_price_valid_from", NEW."s_price_valid_till", NEW."service_id";
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_service_price_before_insert
BEFORE INSERT ON "Additional_services_pricing"
FOR EACH ROW EXECUTE FUNCTION service_price_before_insert();

COMMENT ON COLUMN "Additional_services_pricing"."s_price_valid_till" IS 'current price date_till is 01/01/2099';


CREATE TABLE IF NOT EXISTS "Actual_stays" (
	"stay_id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"room_id" INTEGER NOT NULL,
	"booking_id" BIGINT NOT NULL,
	"check_in" TIMESTAMPTZ NOT NULL,
	"check_out" TIMESTAMPTZ,
	PRIMARY KEY("stay_id"),
	CONSTRAINT chk_in_out_date CHECK (check_out IS NULL OR check_out > check_in)
);
-- one open stay per room
CREATE UNIQUE INDEX uq_one_open_stay_per_room
  ON "Actual_stays" (room_id) WHERE check_out IS NULL;


CREATE TABLE IF NOT EXISTS "Hotels" (
